import{_ as i,c as e,o as r,ag as l}from"./chunks/framework.DfL_BkQ-.js";const d=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy.md","filePath":"zh-CN/guide/privacy.md","lastUpdated":1794112334000}'),t={name:"zh-CN/guide/privacy.md"};function o(s,a,h,n,c,p){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><h2 id="数据收集" tabindex="-1">数据收集 <a class="header-anchor" href="#数据收集" aria-label="Permalink to &quot;数据收集&quot;">​</a></h2><p>开发者不会通过本应用收集任何数据。</p><h3 id="我们不会收集的信息" tabindex="-1">我们不会收集的信息 <a class="header-anchor" href="#我们不会收集的信息" aria-label="Permalink to &quot;我们不会收集的信息&quot;">​</a></h3><ul><li>个人信息</li><li>使用统计</li><li>设备信息</li><li>位置数据</li><li>图片内容或元数据</li><li>浏览记录</li><li>任何其他用户数据</li></ul><h3 id="chrome-扩展" tabindex="-1">Chrome 扩展 <a class="header-anchor" href="#chrome-扩展" aria-label="Permalink to &quot;Chrome 扩展&quot;">​</a></h3><p>Nicasa Chrome 扩展仅为实现看图功能而请求访问页面内容以提取图片地址。该扩展：</p><ul><li>不会读取或存储浏览记录</li><li>不会追踪用户行为</li><li>不会向外部服务器传输任何数据</li><li>仅在浏览器本地处理图片地址</li></ul><h3 id="本地处理" tabindex="-1">本地处理 <a class="header-anchor" href="#本地处理" aria-label="Permalink to &quot;本地处理&quot;">​</a></h3><p>所有图片处理、编辑与查看都在你的设备本地完成，不会把图片或数据上传到外部服务器。</p><h3 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h3><p>Nicasa 在 macOS 上请求以下权限：</p><ul><li><strong>屏幕录制</strong>：截图功能所必需</li><li><strong>辅助功能</strong>：可选，用于悬浮模式相关功能</li><li><strong>文件与文件夹</strong>：访问用户选择的目录以浏览图片</li></ul><p>这些权限可在「系统设置 &gt; 隐私与安全性」中管理。</p><h3 id="第三方服务" tabindex="-1">第三方服务 <a class="header-anchor" href="#第三方服务" aria-label="Permalink to &quot;第三方服务&quot;">​</a></h3><p>Nicasa 未接入任何第三方统计、广告或数据收集服务。</p><h3 id="隐私选项" tabindex="-1">隐私选项 <a class="header-anchor" href="#隐私选项" aria-label="Permalink to &quot;隐私选项&quot;">​</a></h3><p>如果你想行使隐私权利（例如：查阅、删除、可携带或拒绝授权等请求），或你确信 Nicasa 持有关于你的个人数据，可通过以下任一方式提交请求：</p><ul><li>邮箱：nicasa@w3cub.com</li><li>提交隐私 issue：<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li><li>使用我们的隐私选项页面：/zh-CN/guide/privacy-choices</li></ul><p>由于如上所述 Nicasa 并不收集个人数据，许多请求会以「未持有任何个人数据」的确认作为答复。如果未来的版本开始收集个人数据，本页面与隐私选项表单将提供提交与跟踪请求的途径。</p><p>我们力求在 30 天内回应合理的隐私请求。</p><h3 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h3><p>本隐私政策可能会随应用新版本而更新。如有重大变更，我们会通知用户。</p><h3 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h3><p>如对隐私有疑问，请通过 <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub 仓库</a>联系我们。</p>',25)])])}const m=i(t,[["render",o]]);export{d as __pageData,m as default};
